export const coverReference=id=>COVER_REFERENCES.find(r=>r.id===id);
export function recommendedReferences(topic){return [...COVER_REFERENCES].sort((a,b)=>b.tags.filter(t=>topic.includes(t)).length-a.tags.filter(t=>topic.includes(t)).length);}
export const COVER_ATLAS='/cover-references/social-atlas.png';
export const COVER_DESIGN_RULES='Design a complete social-feed cover, not merely a portrait with a caption. Establish one main semantic/visual anchor and readable hierarchy at small mobile thumbnail size. Person, title and optional supporting labels must form an intentional information structure. Use outline, paper/color panels, keyword emphasis, checklist, benefit strip or hand-drawn guide ONLY when useful. Natural photographic backgrounds are welcome: protect text contrast using local treatment, not mandatory flat-color backgrounds. Do not cover the face or accidentally crop essential title/object. Do not force all references into the same palette, pose, title placement or sticker set. Each candidate must vary framing, subject placement, scene or information organization, not just colors. Never invent numerical claims, guaranteed results, testimonials, urgency or test outcomes.';
